 const s=store();saveDeliveryBatch(s,batch());const before=[...s.map],copied=[],calls=[],f=historyView(s,'es',text=>copied.push(text),{versionRequest:async(url,options)=>{calls.push({url,options});return{ok:true,status:200,json:async()=>versionMeta()};}});f.button.onclick();f.query.value='version 8';f.query.oninput();assert.equal(calls.length,0);const entry=f.list.children[0],check=action(entry,'history-check');await check.onclick();assert.equal(calls.length,1);const summary=entry.children.find(n=>n.className==='history-version-summary');assert.match(summary.textContent,/Comprobado.*1 disponible.*0 no disponibles.*0 sin poder comprobar/);assert.ok(summary.dataset.checkedAt);
 const row=entry.children.find(n=>n.tag==='ul').children[0];assert.equal(row.dataset.state,'success');assert.equal(row.children[1].textContent,'Versión preparada');const health=row.children.find(n=>n.className==='history-version-state');assert.equal(health.dataset.versionState,'available');assert.equal(health.textContent,'Versión disponible');assert.equal(check.disabled,false);
