 const s=store();saveDeliveryBatch(s,batch());let release,gate,calls=0;const f=historyView(s,'en',undefined,{versionRequest:async()=>{calls++;if(gate)await gate;return{ok:true,status:200,json:async()=>versionMeta()};}});f.button.onclick();const entry=f.list.children[0],check=action(entry,'history-check'),report=entry.children.find(n=>n.className==='history-version-csv');await check.onclick();report.onclick();assert.match(f.downloads[0].filename,/version-check/);
