 f.query.value='missing';f.query.oninput();await running;release();report.onclick();assert.equal(f.downloads.length,1);assert.equal(f.list.children.length,0);
 gate=undefined;f.clear.onclick();const current=f.list.children[0],currentReport=current.children.find(n=>n.className==='history-version-csv');await action(current,'history-check').onclick();f.dialog.children.find(n=>n.tag==='button').onclick();currentReport.onclick();assert.equal(f.downloads.length,1);f.button.onclick();assert.equal(f.list.children[0].children.find(n=>n.className==='history-version-csv').hidden,true);assert.equal(calls,3);
