  pending[1].resolve({ok:false,status:404});await new Promise(setImmediate);assert.equal(summary.dataset.completed,'0');pending[2].resolve({ok:true,status:200,json:async()=>versionMeta(8,'a')});pending[3].resolve({ok:false,status:503});await second;assert.equal(summary.dataset.completed,undefined);assert.equal(summary.dataset.total,undefined);assert.ok(summary.dataset.checkedAt);assert.match(summary.textContent,language==='es'?/1 disponible.*1 sin poder comprobar.*1 sin enlace/:/1 available.*1 could not be checked.*1 without a confirmed link/);assert.equal(exportCheck.hidden,false);assert.equal(cancel.hidden,true);assert.deepEqual([...s.map],before);
