test('historial vacío/corrupto no permite copia, y una lectura que cambia después de abrir falla sin archivo ni datos perdidos',async()=>{
 for(const raw of [null,'{broken']){const s=store();if(raw!==null)s.map.set(DELIVERY_HISTORY_KEY,raw);const f=historyView(s);f.button.onclick();const backup=f.dialog.children.find(n=>n.className==='history-backup-actions').children[0];assert.equal(backup.disabled,true);await backup.onclick();assert.equal(f.downloads.length,0);}
 for(const raw of [null,'{broken']){const s=store();saveDeliveryBatch(s,batch());const f=historyView(s);f.button.onclick();if(raw===null)s.map.delete(DELIVERY_HISTORY_KEY);else s.map.set(DELIVERY_HISTORY_KEY,raw);const before=[...s.map];await f.dialog.children.find(n=>n.className==='history-backup-actions').children[0].onclick();assert.equal(f.downloads.length,0);assert.match(f.dialog.children.find(n=>n.className==='history-backup-status').textContent,raw===null?/No hay lotes/:/No se puede leer el historial/);assert.deepEqual([...s.map],before);}
});
test('error de descarga no anuncia éxito ni toca el historial; cerrar y abrir descarta callbacks de la sesión anterior',async()=>{
 for(const asyncFailure of [false,true]){const s=store();saveDeliveryBatch(s,batch());const before=[...s.map],f=historyView(s,'en',undefined,{download:()=>asyncFailure?Promise.reject(Error('private')):(()=>{throw Error('private');})()});f.button.onclick();const backup=f.dialog.children.find(n=>n.className==='history-backup-actions').children[0];await backup.onclick();assert.match(f.dialog.children.find(n=>n.className==='history-backup-status').textContent,/download could not be prepared/);assert.equal(backup.disabled,false);assert.deepEqual([...s.map],before);}
 const s=store();saveDeliveryBatch(s,batch());let finish;const f=historyView(s,'es',undefined,{download:()=>new Promise(resolve=>finish=resolve)});f.button.onclick();const backup=f.dialog.children.find(n=>n.className==='history-backup-actions').children[0],note=f.dialog.children.find(n=>n.className==='history-backup-status'),pending=backup.onclick();assert.equal(backup.disabled,true);f.dialog.children.find(n=>n.tag==='button').onclick();f.button.onclick();assert.equal(backup.disabled,false);finish();await pending;assert.equal(note.textContent,'');assert.equal(backup.disabled,false);
});
const restoreUi=f=>{const group=f.dialog.children.find(n=>n.className==='history-backup-actions'),review=f.dialog.children.find(n=>n.className==='history-restore-review');return{input:group.children.find(n=>n.className==='history-restore-file'),review,summary:review.children.find(n=>n.className==='history-restore-summary'),list:review.children.find(n=>n.className==='history-restore-list'),confirm:review.children.find(n=>n.className==='history-restore-confirm'),cancel:review.children.find(n=>n.className==='history-restore-cancel'),status:f.dialog.children.find(n=>n.className==='history-restore-status')};};
const reviewFile=async(u,content)=>{u.input.files=[{size:Buffer.byteLength(content),text:async()=>content}];await u.input.onchange();};
test('revisión bilingüe restaura sólo tras confirmar, mantiene filtros y no ofrece confirmación si todo existe',async()=>{for(const language of ['es','en']){const s=store(),other=store();saveDeliveryBatch(other,batch());const content=deliveryHistoryBackup(other).content,f=historyView(s,language);f.button.onclick();const u=restoreUi(f),before=[...s.map];await reviewFile(u,content);assert.deepEqual([...s.map],before);assert.equal(u.review.hidden,false);assert.equal(u.confirm.hidden,false);assert.match(u.summary.textContent,language==='es'?/1 nuevo.*0 ya existentes/:/1 new.*0 already identical/);u.cancel.onclick();assert.deepEqual([...s.map],before);await reviewFile(u,content);u.confirm.onclick();assert.equal(readDeliveryHistory(s).data.length,1);assert.match(u.status.textContent,language==='es'?/Restauración completada: 1/:/Restore completed: 1/);const saved=[...s.map];await reviewFile(u,content);assert.equal(u.confirm.hidden,true);assert.equal(u.confirm.disabled,true);assert.match(u.summary.textContent,language==='es'?/Todos los lotes ya están guardados/:/All batches are already saved/);u.confirm.onclick();assert.deepEqual([...s.map],saved);}});
test('revisión descarta lecturas tardías al cancelar, cerrar o seleccionar otro archivo y bloquea un historial cambiado',async()=>{for(const change of ['cancel','close','file']){const s=store(),other=store();saveDeliveryBatch(other,batch());const content=deliveryHistoryBackup(other).content,f=historyView(s);f.button.onclick();const u=restoreUi(f);let resolve;u.input.files=[{size:100,text:()=>new Promise(r=>resolve=r)}];const reading=u.input.onchange();if(change==='cancel')u.cancel.onclick();else if(change==='close')f.dialog.children.find(n=>n.tag==='button').onclick();else await reviewFile(u,'{broken');resolve(content);await reading;assert.equal(u.review.hidden,true);assert.equal(u.confirm.disabled,true);assert.equal(readDeliveryHistory(s).data.length,0);}
 const s=store(),other=store();saveDeliveryBatch(other,batch());const f=historyView(s);f.button.onclick();const u=restoreUi(f);await reviewFile(u,deliveryHistoryBackup(other).content);saveDeliveryBatch(s,batch('changed'));const before=[...s.map];u.confirm.onclick();assert.match(u.status.textContent,/El historial ha cambiado/);assert.equal(u.confirm.hidden,true);assert.deepEqual([...s.map],before);
});
test('guía opcional bilingüe cerrada al abrir explica los alcances sin controles, escrituras ni consultas',()=>{
 for(const language of ['es','en']){const s=store();saveDeliveryBatch(s,batch());const before=[...s.map];let requests=0,copies=0;const f=historyView(s,language,async()=>copies++,{versionRequest:async()=>requests++});f.button.onclick();const guide=f.dialog.children.find(n=>n.className==='history-guide');assert.equal(guide.open,false);assert.equal(guide.children[0].tag,'summary');assert.equal(guide.children[1].tag,'ol');assert.equal(guide.children[1].children.length,5);const text=guide.children[1].children.map(n=>n.textContent).join(' ');for(const phrase of language==='es'?['sólo cambia lo que ves','No confirma la reproducción física','no recupera proyectos','versión actual del Creador','acción distinta']:['only change what you see','does not confirm physical playback','does not recover projects','current Creator version','separate action'])assert.ok(text.includes(phrase),phrase);guide.open=true;guide.open=false;assert.equal(requests,0);assert.equal(copies,0);assert.equal(f.downloads.length,0);assert.equal(f.reused.length,0);assert.deepEqual([...s.map],before);guide.open=true;f.button.onclick();assert.equal(guide.open,false);assert.equal(f.list.children.length,1);}
});
